MD5=$(tail -n +552 "$THIS_PATH" | md5sum -)
echo $MD5 | grep ce217ffc6b49d0831991de46718d6c44 >/dev/null
if (( $? )); then
    echo "WARNING: md5sum mismatch of tar archive
expected: ce217ffc6b49d0831991de46718d6c44
